\label{lemma-quasi-compact}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $U$ is quasi-compact, and
\item for every surjection of sheaves
$\coprod_{i \in I} \mathcal{F}_i \to h_U^\#$
there is a finite subset $J \subset I$ such that
$\coprod_{i \in J} \mathcal{F}_i \to h_U^\#$ is surjective.
\end{enumerate}

\label{lemma-image-of-quasi-compact}
\begin{slogan}
Sheaf surjections transmit quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item If $U \to V$ is a morphism of $\mathcal{C}$ such that
$h_U^\# \to h_V^\#$ is surjective and $U$ is quasi-compact, then
$V$ is quasi-compact.
\item If $\mathcal{F} \to \mathcal{G}$ is a surjection of sheaves
of sets and $\mathcal{F}$ is quasi-compact, then $\mathcal{G}$
is quasi-compact.
\end{enumerate}

\label{lemma-coproduct-quasi-compact}
\begin{slogan}
Finite copoducts of sheaves conserve quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site. If $n \geq 1$ and
$\mathcal{F}_1, \ldots, \mathcal{F}_n$ are quasi-compact
sheaves on $\mathcal{C}$, then $\coprod_{i = 1, \ldots, n} \mathcal{F}_i$
is quasi-compact.
